/**
 * Helpers for palette share-link social previews.
 *
 * Share URLs (`/?p=HEX-HEX-HEX-HEX-HEX`) render entirely client-side, so
 * social scrapers that only read the initial HTML see the generic brand OG
 * image instead of the actual palette. The proxy detects known social-crawler
 * user agents and rewrites those requests to `/share`, which emits a minimal
 * HTML document with Open Graph tags pointing at the per-palette image
 * generated by `/api/og` (see ADR-0007).
 *
 * Pure functions only — shared between the proxy, the share route and tests.
 */

/** A palette is always exactly five colors (see CONTEXT.md). */
export const SHARE_COLOR_COUNT = 5;

const HEX_PATTERN = /^[0-9A-Fa-f]{6}$/;

/**
 * Parses a `p` share parameter (`6366F1-8B5CF6-F59E0B-F8FAFC-F1F5F9`) into
 * `#`-prefixed uppercase hex values. Returns `null` for anything that is not
 * exactly five valid 6-digit hex values, mirroring the silent-fallback rule
 * used by `decodePaletteFromUrl`.
 */
export function parseHexColors(
  raw: string | null | undefined
): string[] | null {
  if (!raw) return null;

  const parts = raw.split("-");
  if (parts.length !== SHARE_COLOR_COUNT) return null;
  if (!parts.every((part) => HEX_PATTERN.test(part))) return null;

  return parts.map((part) => `#${part.toUpperCase()}`);
}

/**
 * Re-encodes parsed colors back into the `p` parameter format.
 * Inverse of {@link parseHexColors}.
 */
export function encodeHexColors(colors: string[]): string {
  return colors.map((color) => color.replace("#", "")).join("-");
}

/**
 * User agents of social scrapers that render link previews. These are the
 * consumers that need the per-palette OG tags; everything else (humans,
 * Googlebot) gets the normal application.
 *
 * Google/SEO crawlers are intentionally NOT matched — the canonical tag on
 * `/share` consolidates share URLs into the homepage, so indexing crawlers
 * should keep fetching the real pages.
 */
const SOCIAL_BOT_PATTERN =
  /facebookexternalhit|facebot|twitterbot|discordapp|discordbot|whatsapp|telegrambot|slackbot|slack-imgproxy|linkedinbot|pinterestbot|skypeuripreview|flipboard|viber|redditbot|tumblr|mastodon|bluesky|bytespider|w3c_validator/i;

export function isSocialBot(userAgent: string | null | undefined): boolean {
  if (!userAgent) return false;
  return SOCIAL_BOT_PATTERN.test(userAgent);
}
